Drop View VW_A_IMPORTI_NON_RIDOTTI
GO
Create  View VW_A_IMPORTI_NON_RIDOTTI as SELECT registrazioni.id as id,
registrazioni.importo as importo_registrazione,
ISNULL(SUM(reg_io_assegnazioni.importo),
0) as incassato,
registrazioni.importo - SUM(ISNULL(reg_io_assegnazioni.importo,
0)) as saldo,
registrazioni.idcomune as idcomune FROM registrazioni LEFT OUTER JOIN registrazioni_importi LEFT OUTER JOIN reg_io_assegnazioni ON registrazioni_importi.idcomune = reg_io_assegnazioni.idcomune AND registrazioni_importi.id = reg_io_assegnazioni.fk_riid ON registrazioni.idcomune=registrazioni_importi.idcomune  AND registrazioni.id=registrazioni_importi.fk_rgid WHERE (registrazioni_importi.flag_nonprevincassi = 0 or registrazioni_importi.flag_nonprevincassi  is NULL)  GROUP BY registrazioni.id,
registrazioni.importo,
registrazioni.software,
registrazioni.idcomune
GO
Drop View VW_A_IMPORTI_RIDOTTI
GO
Create  View VW_A_IMPORTI_RIDOTTI as SELECT registrazioni.id as id,
registrazioni.importo as importo_registrazione,
ISNULL(SUM(reg_io_assegnazioni.importo),
0) as incassato,
SUM(registrazioni_importi.importo) - SUM(ISNULL(reg_io_assegnazioni.importo,
0)) as saldo,
registrazioni.idcomune as idcomune FROM registrazioni LEFT OUTER JOIN registrazioni_importi LEFT OUTER JOIN reg_io_assegnazioni ON registrazioni_importi.idcomune = reg_io_assegnazioni.idcomune AND registrazioni_importi.id = reg_io_assegnazioni.fk_riid ON registrazioni.idcomune=registrazioni_importi.idcomune  AND registrazioni.id=registrazioni_importi.fk_rgid WHERE (registrazioni_importi.flag_nonprevincassi = 1 or registrazioni_importi.flag_nonprevincassi  is NULL)  GROUP BY registrazioni.id,
registrazioni.importo,
registrazioni.software,
registrazioni.idcomune
GO
Drop View VW_ALBEROPROC
GO
Create  View VW_ALBEROPROC as SELECT alberoproc.idcomune,
alberoproc.software,
alberoproc.sc_id,
alberoproc.sc_codice,
alberoproc.sc_padre,
ISNULL(case alberoproc_l4.sc_descrizione when null then '' ELSE ISNULL(alberoproc_l4.sc_descrizione,
'') + ISNULL(' - ',
'') end,
'') + ISNULL(case alberoproc_l3.sc_descrizione when null then '' ELSE ISNULL(alberoproc_l3.sc_descrizione,
'') + ISNULL(' - ',
'') end,
'') + ISNULL(case alberoproc_l2.sc_descrizione when null then '' ELSE ISNULL(alberoproc_l2.sc_descrizione,
'') + ISNULL(' - ',
'') end,
'') + ISNULL(case alberoproc_l1.sc_descrizione when null then '' ELSE ISNULL(alberoproc_l1.sc_descrizione,
'') + ISNULL(' - ',
'') end,
'') + ISNULL(alberoproc.sc_descrizione,
'') as sc_descrizione,
ISNULL(case alberoproc_l4.sc_descrizione when null then '' ELSE ISNULL(alberoproc_l4.sc_descrizione,
'') + ISNULL(' - ',
'') end,
'') + ISNULL(case alberoproc_l3.sc_descrizione when null then '' ELSE ISNULL(alberoproc_l3.sc_descrizione,
'') + ISNULL(' - ',
'') end,
'') + ISNULL(case alberoproc_l2.sc_descrizione when null then '' ELSE ISNULL(alberoproc_l2.sc_descrizione,
'') + ISNULL(' - ',
'') end,
'') + ISNULL(case alberoproc_l1.sc_descrizione when null then '' ELSE alberoproc_l1.sc_descrizione end,
'') as sc_descrizionePadre,
alberoproc.sc_descrizione as sc_descrizioneBreve,
alberoproc.sc_ordine as ordine0,
ISNULL(alberoproc_l1.sc_ordine,
0) as ordine1,
ISNULL(alberoproc_l2.sc_ordine,
0) as ordine2,
ISNULL(alberoproc_l3.sc_ordine,
0) as ordine3,
ISNULL(alberoproc_l4.sc_ordine,
0) as ordine4,
case alberoproc.fkcodicemercato when null then case alberoproc_l1.fkcodicemercato when null then case alberoproc_l2.fkcodicemercato when null then case alberoproc_l3.fkcodicemercato when null then alberoproc_l4.fkcodicemercato ELSE alberoproc_l3.fkcodicemercato end ELSE alberoproc_l2.fkcodicemercato end ELSE alberoproc_l1.fkcodicemercato end ELSE  alberoproc.fkcodicemercato end as fkcodicemercato,
case alberoproc.fkidmercatiuso  when null then case alberoproc_l1.fkidmercatiuso  when null then case alberoproc_l2.fkidmercatiuso  when null then case alberoproc_l3.fkidmercatiuso  when null then alberoproc_l4.fkidmercatiuso  ELSE alberoproc_l3.fkidmercatiuso  end ELSE alberoproc_l2.fkidmercatiuso  end ELSE alberoproc_l1.fkidmercatiuso  end ELSE  alberoproc.fkidmercatiuso end as fkidmercatiuso,
alberoproc.sc_attivo,
alberoproc.progressivoistanze FROM alberoproc LEFT OUTER JOIN alberoproc alberoproc_l1 LEFT OUTER JOIN alberoproc alberoproc_l2 LEFT OUTER JOIN alberoproc alberoproc_l3 LEFT OUTER JOIN alberoproc alberoproc_l4 ON alberoproc_l3.idcomune=alberoproc_l4.idcomune  AND alberoproc_l3.software=alberoproc_l4.software  AND substring(alberoproc_l3.sc_codice, 0,
  len(alberoproc_l3.sc_codice) - 2)=alberoproc_l4.sc_codice ON alberoproc_l2.idcomune=alberoproc_l3.idcomune  AND alberoproc_l2.software=alberoproc_l3.software  AND substring(alberoproc_l2.sc_codice, 0,
  len(alberoproc_l2.sc_codice) - 2)=alberoproc_l3.sc_codice ON alberoproc_l1.idcomune=alberoproc_l2.idcomune  AND alberoproc_l1.software=alberoproc_l2.software  AND substring(alberoproc_l1.sc_codice, 0,
  len(alberoproc_l1.sc_codice) - 2)=alberoproc_l2.sc_codice ON alberoproc.idcomune=alberoproc_l1.idcomune  AND alberoproc.software=alberoproc_l1.software  AND substring(alberoproc.sc_codice, 0,
  len(alberoproc.sc_codice) -2)=alberoproc_l1.sc_codice
GO
