Drop View VW_ANAGRAFE_LOCALIZZAZIONI
GO
Create  View VW_ANAGRAFE_LOCALIZZAZIONI as SELECT ANAGRAFE.IDCOMUNE,
ANAGRAFE.CODICEANAGRAFE,
RTrim(LTrim(ISNULL(ANAGRAFE.NOMINATIVO,
'')) + ISNULL(' ',
'') + ISNULL(ANAGRAFE.NOME,
'')) as NOMINATIVO,
ANAGRAFE.INDIRIZZO as INDIRIZZO_RESIDENZA,
ISNULL(case ISNULL(ANAGRAFE.CAP,
'0') when '0' then '' ELSE ISNULL(ANAGRAFE.CAP,
'') + ISNULL(', ',
'') end,
'') + ISNULL(case ISNULL(COMUNI_RESIDENZA.COMUNE,
'0') when '0' then '' ELSE ISNULL(COMUNI_RESIDENZA.COMUNE,
'') + ISNULL('',
'') end,
'') + ISNULL(case ISNULL(ANAGRAFE.CITTA,
'0') when '0' then '' ELSE ISNULL(', ',
'') + ISNULL(ANAGRAFE.CITTA,
'') + ISNULL('',
'') end,
'') + ISNULL(case ISNULL(ANAGRAFE.PROVINCIA,
'0') when '0' then '' ELSE ISNULL(' (',
'') + ISNULL(ANAGRAFE.PROVINCIA,
'') + ISNULL(')',
'') end,
'') as LOCALIZZAZIONE_RESIDENZA,
ANAGRAFE.INDIRIZZOCORRISPONDENZA as INDIRIZZO_CORRISPONDENZA,
ISNULL(case ISNULL(ANAGRAFE.CAPCORRISPONDENZA,
'0') when '0' then '' ELSE ISNULL(ANAGRAFE.CAPCORRISPONDENZA,
'') + ISNULL(', ',
'') end,
'') + ISNULL(case ISNULL(COMUNI_CORRISPONDENZA.COMUNE,
'0') when '0' then '' ELSE ISNULL(COMUNI_CORRISPONDENZA.COMUNE,
'') + ISNULL('',
'') end,
'') + ISNULL(case ISNULL(ANAGRAFE.CITTACORRISPONDENZA,
'0') when '0' then '' ELSE ISNULL(', ',
'') + ISNULL(ANAGRAFE.CITTACORRISPONDENZA,
'') + ISNULL('',
'') end,
'') + ISNULL(case ISNULL(ANAGRAFE.PROVINCIACORRISPONDENZA,
'0') when '0' then '' ELSE ISNULL(' (',
'') + ISNULL(ANAGRAFE.PROVINCIACORRISPONDENZA,
'') + ISNULL(')',
'') end,
'') as LOCALIZZAZIONE_CORRISPONDENZA,
case ISNULL(ANAGRAFE.INDIRIZZOCORRISPONDENZA,
'0') when '0' then 0 ELSE 1 end as IS_CORRISPONDENZA FROM ANAGRAFE LEFT OUTER JOIN COMUNI COMUNI_RESIDENZA ON ANAGRAFE.COMUNERESIDENZA = COMUNI_RESIDENZA.CODICECOMUNE LEFT OUTER JOIN COMUNI COMUNI_CORRISPONDENZA ON ANAGRAFE.COMUNECORRISPONDENZA = COMUNI_CORRISPONDENZA.CODICECOMUNE
GO
Drop View VW_A_REG_IMPORTI_DEBITI
GO
Create  View VW_A_REG_IMPORTI_DEBITI as 
SELECT REGISTRAZIONI.ID as ID_REGISTRAZIONE,
REGISTRAZIONI.SOFTWARE,
REGISTRAZIONI.IDCOMUNE,
REGISTRAZIONI_IMPORTI.ID,
REGISTRAZIONI_IMPORTI.IMPORTO,
REGISTRAZIONI_IMPORTI.NR_RATA as RATA,
SUM(REG_IO_ASSEGNAZIONI.IMPORTO) as INCASSATO FROM REGISTRAZIONI_IMPORTI LEFT OUTER JOIN REG_IO_ASSEGNAZIONI ON REGISTRAZIONI_IMPORTI.IDCOMUNE=REG_IO_ASSEGNAZIONI.IDCOMUNE  AND REGISTRAZIONI_IMPORTI.ID=REG_IO_ASSEGNAZIONI.FK_RIID,
REGISTRAZIONI WHERE REGISTRAZIONI.IDCOMUNE = REGISTRAZIONI_IMPORTI.IDCOMUNE AND REGISTRAZIONI.ID = REGISTRAZIONI_IMPORTI.FK_RGID AND REGISTRAZIONI_IMPORTI.FLAG_NONPREVINCASSI = 0 
GROUP BY REGISTRAZIONI.ID,
REGISTRAZIONI_IMPORTI.ID,
REGISTRAZIONI_IMPORTI.IMPORTO,
REGISTRAZIONI_IMPORTI.NR_RATA,
REGISTRAZIONI.SOFTWARE,
REGISTRAZIONI.IDCOMUNE
HAVING ISNULL(SUM(REG_IO_ASSEGNAZIONI.IMPORTO), 0) < REGISTRAZIONI_IMPORTI.IMPORTO  
GO
Drop View VW_A_REGISTRAZIONI_DEBITI
GO
Create  View VW_A_REGISTRAZIONI_DEBITI as SELECT id_REGISTRAZIONE,
IDCOMUNE,
SOFTWARE,
rata as rata_non_pagata,
SUM(importo) as importo_rata,
ISNULL(SUM(incassato),
 0) as incassato_rata,
(SUM(IMPORTO) - ISNULL(SUM(incassato),
 0)) as DA_INCASSARE FROM  VW_A_REG_IMPORTI_DEBITI 	 GROUP BY ID_REGISTRAZIONE,
SOFTWARE,
IDCOMUNE,rata
GO
