Create  View VW_A_SALDO_RIDOTTI as SELECT registrazioni.id as id,
SUM(registrazioni_importi.importo) saldo,
registrazioni.idcomune as idcomune FROM  registrazioni,
 registrazioni_importi WHERE registrazioni_importi.idcomune = registrazioni.idcomune and registrazioni_importi.fk_rgid = registrazioni.id and registrazioni_importi.flag_nonprevincassi = 1 GROUP BY registrazioni.id,
registrazioni.idcomune
