Drop View VW_ASSENZECONCESSIONARI
GO
Create  View VW_ASSENZECONCESSIONARI as 
SELECT TOP 100 PERCENT COUNT(*) as numero_assenze,
mercati.codicemercato,
MERCATI.descrizione as MERCATO,
mercati_uso.id as codiceuso,
mercati_uso.descrizione as USO,
mercati_d.idposteggio,
MERCATI_D.codiceposteggio as POSTEGGIO,
anagrafe.codiceanagrafe,
ANAGRAFE.NOMINATIVO,
ANAGRAFE.NOME,
mercatipresenze_t.anno,
mercatipresenze_t.software,
mercatipresenze_t.idcomune FROM  MERCATIPRESENZE_D,
 ANAGRAFE,
 MERCATI,
 MERCATI_USO,
 MERCATI_D,
 MERCATIPRESENZE_T WHERE MERCATIPRESENZE_D.IDCOMUNE = mercatipresenze_t.idcomune and MERCATIPRESENZE_D.fkidtestata = mercatipresenze_t.id and mercatipresenze_d.idcomune = anagrafe.idcomune and mercatipresenze_d.codiceconcessionario = anagrafe.codiceanagrafe and MERCATI.IDCOMUNE = mercatipresenze_T.idcomune and mercati.codicemercato = mercatipresenze_T.fkcodicemercato and MERCATI_USO.IDCOMUNE = MERCATIPRESENZE_T.IDCOMUNE and MERCATI_USO.id = MERCATIPRESENZE_T.fkidmercatiuso and mercati_d.idcomune = MERCATIPRESENZE_D.idcomune and mercati_d.idposteggio = mercatipresenze_d.fkidposteggio and codiceconcessionario  is not  NULL and ( ( MERCATIPRESENZE_D.CODICEANAGRAFE ! = CODICECONCESSIONARIO) or MERCATIPRESENZE_D.CODICEANAGRAFE  is  NULL ) and ( flag_assenza_giust  is  NULL or flag_assenza_giust = 0) GROUP BY anagrafe.nominativo,
anagrafe.nomE,
MERCATI.descrizione,
mercati_uso.descrizione,
mercati_d.idposteggio,
MERCATI_D.codiceposteggio,
mercati.codicemercato,
mercatipresenze_t.anno,
mercatipresenze_t.software,
mercatipresenze_t.idcomune,
anagrafe.codiceanagrafe,
mercati_uso.id ORDER BY mercato,uso,
posteggio,
nominativo,nome
GO
Drop View VW_BATCH_SCADENZARIO
GO
Create  View VW_BATCH_SCADENZARIO as 
SELECT mdf.codicemovimento as id,
getdate() as dataelaborazione,
mdf.idcomune as idcomune,
istanze.software as software,
mdf.codiceistanza as codiceistanza,
mf.codicemovimento as codicemovimento,
ISNULL(mf.movimento,
 tmf.movimento) as descrmovimento,
mdf.tipomovimento as tipomovimentodafare,
ISNULL(mdf.movimento,
 tm.movimento) as descrmovimentodafare,
mdf.codiceinventario as codiceinventario,
mdf.codiceamministrazione as CODICEAMMINISTRAZIONE,
mdf.data_scadenza as datascadenza FROM  movimenti mdf INNER JOIN istanze ON istanze.idcomune       =mdf.idcomune AND istanze.codiceistanza =mdf.codiceistanza INNER JOIN tipimovimento tm ON tm.idcomune       =mdf.idcomune AND tm.tipomovimento =mdf.tipomovimento LEFT JOIN movimenti_contromovimenti mcm ON mcm.idcomune=mdf.idcomune AND mcm.codicecontromovimento=mdf.codicemovimento LEFT JOIN movimenti mf ON mf.idcomune=mcm.idcomune and mf.codicemovimento=mcm.codicemovimento left join tipimovimento tmf on tmf.idcomune=mf.idcomune and  tmf.tipomovimento=mf.tipomovimento WHERE mdf.data  is  NULL and (mdf.flag_disabilitato  is  NULL or mdf.flag_disabilitato = 0)
GO
