VW_CONCESSIONILISTA.CONC_POS_SUPERFICIE,
VW_CONCESSIONILISTA.POST_IDTIPOSPAZIO,
VW_CONCESSIONILISTA.POST_TIPOSPAZIO,
VW_CONCESSIONILISTA.CONC_IDMERCATIUSO,
VW_CONCESSIONILISTA.CONC_DESCRIZIONEUSO,
VW_CONCESSIONILISTA.PESO_MERCATO,
VW_CONCESSIONILISTA.MERC_IDUSO FROM  I_ATTIVITA,
 VW_CONCESSIONILISTA,
 ISTANZE WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID and VW_CONCESSIONILISTA.IDCOMUNE = ISTANZE.IDCOMUNE and VW_CONCESSIONILISTA.IST_CODICEISTANZA = ISTANZE.CODICEISTANZA
GO
