Create  View VW_I_ATTIVITAINFORMAZIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA,
ISTANZEATTIVITA.CODICEISTANZA,
ISTANZEATTIVITA.CODICEATTIVITA,
ISTANZEATTIVITA.METRIQ,
ISTANZEATTIVITA.NOTE,
ISTANZEATTIVITA.IDCOMUNE,
ISTANZEATTIVITA.SOFTWARE,
ISTANZEATTIVITA.IDATTIVITA FROM  I_ATTIVITA,
 ISTANZEATTIVITA WHERE ISTANZEATTIVITA.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZEATTIVITA.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA
GO
Drop View VW_I_ATTIVITALISTA
GO
Create  View VW_I_ATTIVITALISTA as SELECT I_ATTIVITA.CODICEISTANZAULTIMA as I_CODICEISTANZAULTIMA,
I_ATTIVITA.ID as I_IDATTIVITA,
I_ATTIVITA.IDCOMUNE,
I_ATTIVITA.ATTIVA,
I_ATTIVITA.OPERANTE,
ISTANZE.SOFTWARE,
I_ATTIVITA.DENOMINAZIONE,
ISTANZE.NUMEROISTANZA,
ISTANZE.CODICERICHIEDENTE,
ISNULL(T_RICHIEDENTE.NOMINATIVO,
'') + ISNULL(' ',
'') + ISNULL(T_RICHIEDENTE.NOME,
'') as RICHIEDENTE,
RTrim(LTrim(ISNULL(T_RICHIEDENTE.CODICEFISCALE,
'')) + ISNULL(' ',
'') + ISNULL(T_RICHIEDENTE.PARTITAIVA,
'')) as CF_PIVA_RICHIEDENTE,
ISTANZE.FKCODICESOGGETTO,
TIPISOGGETTO.TIPOSOGGETTO,
ISTANZE.CODICECOMUNE,
ISTANZE.CODICETITOLARELEGALE,
RTrim(LTrim(ISNULL(T_AZIENDARICHIEDENTE.NOMINATIVO,
'')) + ISNULL(' ',
'') + ISNULL(T_AZIENDARICHIEDENTE.NOME,
'')) as AZIENDARICHIEDENTE,
RTrim(LTrim(ISNULL(T_AZIENDARICHIEDENTE.CODICEFISCALE,
'')) + ISNULL(' ',
'') + ISNULL(T_AZIENDARICHIEDENTE.PARTITAIVA,
'')) as CF_PIVA_AZIENDARICHIEDENTE,
ISTANZESTRADARIO.CODICESTRADARIO,
ISNULL(STRADARIO.PREFISSO,
'') + ISNULL(' ',
'') + ISNULL(STRADARIO.DESCRIZIONE,
'') + ISNULL(',',
'') + ISNULL(ISNULL(ISTANZESTRADARIO.CIVICO,''),
'') + ISNULL(ISNULL(ISTANZESTRADARIO.COLORE,''),
'') as LOCALIZZAZIONE,
ISTANZESTRADARIO.CIVICO FROM ISTANZE LEFT OUTER JOIN ANAGRAFE T_AZIENDARICHIEDENTE ON ISTANZE.IDCOMUNE=T_AZIENDARICHIEDENTE.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=T_AZIENDARICHIEDENTE.CODICEANAGRAFE  LEFT OUTER JOIN TIPISOGGETTO ON ISTANZE.IDCOMUNE=TIPISOGGETTO.IDCOMUNE  AND ISTANZE.FKCODICESOGGETTO=TIPISOGGETTO.CODICETIPOSOGGETTO,
I_ATTIVITA,
ANAGRAFE T_RICHIEDENTE,
ISTANZESTRADARIO,
STRADARIO WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA AND T_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND T_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND ISTANZESTRADARIO.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZESTRADARIO.CODICEISTANZA = ISTANZE.CODICEISTANZA AND ISTANZESTRADARIO.PRIMARIO = 1 AND STRADARIO.IDCOMUNE = ISTANZESTRADARIO.IDCOMUNE AND STRADARIO.CODICESTRADARIO = ISTANZESTRADARIO.CODICESTRADARIO 
GO
