Create  View VW_I_ATTIVITASOGGETTICOLLEGATI as SELECT I_ATTIVITA.ID as I_IDATTIVITA,
ISTANZERICHIEDENTI.CODICEISTANZA,
ISTANZERICHIEDENTI.CODICERICHIEDENTE,
ISTANZERICHIEDENTI.CODICETIPOSOGGETTO,
ISTANZERICHIEDENTI.IDCOMUNE,
ISTANZERICHIEDENTI.CODICEANAGRAFECOLL FROM  I_ATTIVITA,
 ISTANZERICHIEDENTI WHERE ISTANZERICHIEDENTI.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZERICHIEDENTI.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA UNION Select I_ATTIVITA.ID as I_IDATTIVITA,
ISTANZE.CODICEISTANZA,
ISTANZE.CODICERICHIEDENTE,
 ISTANZE.FKCODICESOGGETTO as CODICETIPOSOGGETTO,
ISTANZE.IDCOMUNE,
 ISTANZE.CODICETITOLARELEGALE as CODICEANAGRAFECOLL From I_ATTIVITA,
 ISTANZE Where ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA UNION Select I_ATTIVITA.ID as I_IDATTIVITA,
ISTANZE.CODICEISTANZA,
ISTANZE.CODICETITOLARELEGALE as CODICERICHIEDENTE,
 -1 as CODICETIPOSOGGETTO,
ISTANZE.IDCOMUNE,
 -1 as CODICEANAGRAFECOLL From I_ATTIVITA,
 ISTANZE Where ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA and ISTANZE.CODICETITOLARELEGALE is not null
GO
