Drop View VW_ISTANZECONCESSIONILISTA
GO
Create  View VW_ISTANZECONCESSIONILISTA as 
  SELECT AUTORIZZAZIONI.IDCOMUNE,
    AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE,
    AUTORIZZAZIONI.DATA_CESSAZIONE         AS DATA_STORICO,
    ISTANZE.SOFTWARE,
    ISTANZE.CODICEISTANZA                         AS IST_CODICEISTANZA,
    ISTANZE.NUMEROISTANZA                         AS IST_NUMEROISTANZA ,
    istanze.codicerichiedente                     AS ist_codicerichiedente ,
    AUTORIZZAZIONI.ID                             AS CONC_ID ,
    AUTORIZZAZIONI.AUTORIZNUMERO                  AS CONC_NUMERO ,
    AUTORIZZAZIONI.AUTORIZDATA                    AS CONC_DATARILASCIO ,
    AUTORIZZAZIONI.AUTORIZDATA                    AS DATARILASCIO,
    AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA       AS CONC_DATASCADENZA ,
    AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO ,
    CONCESSIONITIPI.DESCRIZIONE                   AS CONC_TIPO ,
    AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA        AS CONC_STAGIONALEA ,
    AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA       AS CONC_STAGIONALEDA ,
    AUTORIZZAZIONI.FLAG_ATTIVA                    AS CONC_ATTIVA ,
    AUTORIZZAZIONI.FK_CODICEANAGRAFE              AS CONC_CODICETITOLARE ,
    TITOLARE.NOMINATIVO + ' ' + TITOLARE.NOME     AS CONC_TITOLARE ,
    titolare.codicefiscale      AS conc_tit_cf ,
    TITOLARE.PARTITAIVA         AS CONC_TIT_PIVA ,
    TITOLARE.TIPOANAGRAFE       AS CONC_TIT_TIPOANAGRAFE,
    AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO ,
    AUT_COLLEGATA.AUTORIZDATA   AS AUT_DATA ,
    AUT_COLLEGATA.AUTORIZDATA ,
    AUT_COLLEGATA.FKIDREGISTRO       AS AUT_CODREGISTRO,
    TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO ,
    IST_RICHIEDENTE.NOMINATIVO + ' ' + IST_RICHIEDENTE.NOME      AS IST_NOMINATIVO,
    IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE,
    IST_AZIENDA.NOMINATIVO + ' ' + IST_AZIENDA.NOME              AS IST_NOMINATIVOAZIENDA ,
    IST_AZIENDA.TIPOANAGRAFE                    AS IST_AZI_TIPOANAGRAFE,
    ist_richiedente.codicefiscale               AS ist_codicefiscale ,
    IST_RICHIEDENTE.PARTITAIVA                  AS IST_PARTITAIVA ,
    CAUS_ATTUALE.DESCRIZIONE                    AS ICONC_CAUSALE ,
    AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE        AS ICONC_CODICECAUSALESTORICO,
    CAUS_STORICO.DESCRIZIONE                    AS ICONC_CAUSALESTORICO ,
    AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO ,
    MERCATI.DESCRIZIONE                         AS CONC_MERCATO ,
    MERCATI.ATTIVO                              AS MERC_ATTIVO ,
    AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO   AS CONC_IDPOSTEGGIO ,
    MERCATI_D.CODICEPOSTEGGIO                   AS CONC_POSTEGGIO ,
    MERCATI_D.LARGHEZZA                         AS CONC_POS_LARGHEZZA ,
    MERCATI_D.LUNGHEZZA                         AS CONC_POS_LUNGHEZZA ,
    MERCATI_D.SUPERFICIE                        AS CONC_POS_SUPERFICIE ,
    MERCATI_D.FKCODICETIPOSPAZIO                AS POST_IDTIPOSPAZIO ,
    POSTEGGITIPOSPAZIO.TIPOSPAZIO               AS POST_TIPOSPAZIO ,
    AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO  AS CONC_IDMERCATIUSO ,
    MERCATI_USO.DESCRIZIONE                     AS CONC_DESCRIZIONEUSO ,
    MERCATI_USO.PESO                            AS PESO_MERCATO ,
    MERCATI_USO.FKCODICEUSO                     AS MERC_IDUSO
  FROM AUTORIZZAZIONI 
    JOIN AUTORIZZAZIONI_CONCESSIONI
	ON AUTORIZZAZIONI.IDCOMUNE       =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND AUTORIZZAZIONI.id            =AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE
    INNER JOIN CONCESSIONITIPI 
	ON CONCESSIONITIPI.TIPOCONCESSIONE =AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE
    INNER JOIN ANAGRAFE TITOLARE
	ON TITOLARE.IDCOMUNE               =AUTORIZZAZIONI.IDCOMUNE
	AND TITOLARE.CODICEANAGRAFE         =AUTORIZZAZIONI.FK_CODICEANAGRAFE
    INNER JOIN CONCESSIONICAUSALI CAUS_ATTUALE 
	ON CAUS_ATTUALE.IDCOMUNE           =AUTORIZZAZIONI.IDCOMUNE
	AND CAUS_ATTUALE.CODICECAUSALE      =AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE
    INNER JOIN ISTANZE 
	ON ISTANZE.IDCOMUNE                =AUTORIZZAZIONI.IDCOMUNE
	AND ISTANZE.CODICEISTANZA           =AUTORIZZAZIONI.FKIDISTANZA
    INNER JOIN ANAGRAFE IST_RICHIEDENTE 
	ON IST_RICHIEDENTE.IDCOMUNE        =ISTANZE.IDCOMUNE
	AND IST_RICHIEDENTE.CODICEANAGRAFE  =ISTANZE.CODICERICHIEDENTE
    INNER JOIN MERCATI 
	ON MERCATI.IDCOMUNE                =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND MERCATI.CODICEMERCATO           =AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO
    INNER JOIN MERCATI_D 
	ON MERCATI_D.IDCOMUNE              =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND MERCATI_D.IDPOSTEGGIO           =AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO
    INNER JOIN MERCATI_USO 
	ON MERCATI_USO.IDCOMUNE            =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND MERCATI_USO.ID                  =AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO
    LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA 
	ON AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE = AUT_COLLEGATA.IDCOMUNE
	AND AUT_COLLEGATA.id              =AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA
    LEFT OUTER JOIN TIPOLOGIAREGISTRI 
	ON TIPOLOGIAREGISTRI.IDCOMUNE   =AUTORIZZAZIONI.IDCOMUNE
	AND TIPOLOGIAREGISTRI.TR_ID      =AUTORIZZAZIONI.FKIDREGISTRO
    LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO 
	ON CAUS_STORICO.IDCOMUNE        =AUTORIZZAZIONI.IDCOMUNE
	AND CAUS_STORICO.CODICECAUSALE   =AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE
    LEFT OUTER JOIN POSTEGGITIPOSPAZIO 
	ON POSTEGGITIPOSPAZIO.IDCOMUNE  =MERCATI_D.IDCOMUNE
	AND POSTEGGITIPOSPAZIO.CODICE    =MERCATI_D.FKCODICETIPOSPAZIO
    LEFT OUTER JOIN ANAGRAFE IST_AZIENDA 
	ON IST_AZIENDA.IDCOMUNE         =ISTANZE.IDCOMUNE
	AND IST_AZIENDA.CODICEANAGRAFE   =ISTANZE.CODICETITOLARELEGALE
  UNION
  SELECT AUTORIZZAZIONI_SUBENTRI.IDCOMUNE ,
    autorizzazioni_subentri.fk_causale_acquisizione AS iconc_codicecausale,
    AUTORIZZAZIONI_SUBENTRI.DATA_CESSAZIONE         AS DATA_STORICO ,
    ISTANZE.SOFTWARE ,
    ISTANZE.CODICEISTANZA                         AS IST_CODICEISTANZA ,
    ISTANZE.NUMEROISTANZA                         AS IST_NUMEROISTANZA ,
    ISTANZE.CODICERICHIEDENTE                     AS IST_CODICERICHIEDENTE ,
    autorizzazioni_subentri.id                    AS conc_id ,
    AUTORIZZAZIONI_SUBENTRI.AUTORIZNUMERO         AS CONC_NUMERO ,
    AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA           AS CONC_DATARILASCIO ,
    AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA           AS DATARILASCIO,
    AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA       AS CONC_DATASCADENZA ,
    AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO ,
    CONCESSIONITIPI.DESCRIZIONE                   AS CONC_TIPO ,
    AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA        AS CONC_STAGIONALEA ,
    AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA       AS CONC_STAGIONALEDA ,
    0                                             AS CONC_ATTIVA ,
    AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE     AS CONC_CODICETITOLARE ,
    TITOLARE.NOMINATIVO + ' ' + TITOLARE.NOME     AS CONC_TITOLARE ,
    titolare.codicefiscale      AS conc_tit_cf ,
    TITOLARE.PARTITAIVA         AS CONC_TIT_PIVA ,
    TITOLARE.TIPOANAGRAFE       AS CONC_TIT_TIPOANAGRAFE,
    AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO ,
    AUT_COLLEGATA.AUTORIZDATA   AS AUT_DATA ,
    AUT_COLLEGATA.AUTORIZDATA ,
    AUT_COLLEGATA.FKIDREGISTRO       AS AUT_CODREGISTRO,
    TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO ,
    IST_RICHIEDENTE.NOMINATIVO + ' ' + IST_RICHIEDENTE.NOME      AS IST_NOMINATIVO,
    IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE,
    IST_AZIENDA.NOMINATIVO + ' ' + IST_AZIENDA.NOME              AS IST_NOMINATIVOAZIENDA ,
    IST_AZIENDA.TIPOANAGRAFE                      AS IST_AZI_TIPOANAGRAFE,
    IST_RICHIEDENTE.CODICEFISCALE                 AS IST_CODICEFISCALE ,
    IST_RICHIEDENTE.PARTITAIVA                    AS IST_PARTITAIVA ,
    CAUS_ATTUALE.DESCRIZIONE                      AS ICONC_CAUSALE ,
    AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO,
    CAUS_STORICO.DESCRIZIONE                      AS ICONC_CAUSALESTORICO ,
    autorizzazioni_concessioni.fk_codicemercato   AS conc_idmercato ,
    MERCATI.DESCRIZIONE                           AS CONC_MERCATO ,
    MERCATI.ATTIVO                                AS MERC_ATTIVO ,
    AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO     AS CONC_IDPOSTEGGIO ,
    mercati_d.codiceposteggio                     AS conc_posteggio ,
    MERCATI_D.LARGHEZZA                           AS CONC_POS_LARGHEZZA ,
    MERCATI_D.LUNGHEZZA                           AS CONC_POS_LUNGHEZZA ,
    mercati_d.superficie                          AS conc_pos_superficie ,
    MERCATI_D.FKCODICETIPOSPAZIO                  AS POST_IDTIPOSPAZIO ,
    POSTEGGITIPOSPAZIO.TIPOSPAZIO                 AS POST_TIPOSPAZIO ,
    AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO    AS CONC_IDMERCATIUSO ,
    MERCATI_USO.DESCRIZIONE                       AS CONC_DESCRIZIONEUSO ,
    MERCATI_USO.PESO                              AS PESO_MERCATO ,
    MERCATI_USO.FKCODICEUSO                       AS MERC_IDUSO
  FROM AUTORIZZAZIONI_SUBENTRI 
    INNER JOIN AUTORIZZAZIONI_CONCESSIONI 
	ON AUTORIZZAZIONI_SUBENTRI.IDCOMUNE =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND AUTORIZZAZIONI_SUBENTRI.id         =AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE
    INNER JOIN CONCESSIONITIPI 
	ON CONCESSIONITIPI.TIPOCONCESSIONE    =AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE
    INNER JOIN ANAGRAFE TITOLARE 
	ON TITOLARE.IDCOMUNE                  =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE
	AND TITOLARE.CODICEANAGRAFE            =AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE
    INNER JOIN CONCESSIONICAUSALI CAUS_ATTUALE 
	ON CAUS_ATTUALE.IDCOMUNE              =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE
	AND CAUS_ATTUALE.CODICECAUSALE         =AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE
    INNER JOIN ISTANZE 
	ON ISTANZE.IDCOMUNE                =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE
	AND ISTANZE.CODICEISTANZA           =AUTORIZZAZIONI_SUBENTRI.FKIDISTANZA
    INNER JOIN ANAGRAFE IST_RICHIEDENTE 
	ON IST_RICHIEDENTE.IDCOMUNE        =ISTANZE.IDCOMUNE
	AND IST_RICHIEDENTE.CODICEANAGRAFE  =ISTANZE.CODICERICHIEDENTE
    INNER JOIN MERCATI 
	ON MERCATI.IDCOMUNE                =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND MERCATI.CODICEMERCATO           =AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO
    INNER JOIN MERCATI_D 
	ON MERCATI_D.IDCOMUNE              =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND MERCATI_D.IDPOSTEGGIO           =AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO	
    INNER JOIN POSTEGGITIPOSPAZIO 
	ON POSTEGGITIPOSPAZIO.IDCOMUNE  =MERCATI_D.IDCOMUNE
	AND POSTEGGITIPOSPAZIO.CODICE    =MERCATI_D.FKCODICETIPOSPAZIO
    INNER JOIN MERCATI_USO 
	ON MERCATI_USO.IDCOMUNE            =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND MERCATI_USO.ID                  =AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO
    LEFT OUTER JOIN ANAGRAFE IST_AZIENDA
	ON IST_AZIENDA.IDCOMUNE         =ISTANZE.IDCOMUNE
	AND IST_AZIENDA.CODICEANAGRAFE   =ISTANZE.CODICETITOLARELEGALE
    LEFT OUTER JOIN AUTORIZZAZIONI AUT_COLLEGATA 
	ON AUT_COLLEGATA.IDCOMUNE          =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE
	AND AUT_COLLEGATA.ID                =AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA
    LEFT OUTER JOIN TIPOLOGIAREGISTRI 
	ON TIPOLOGIAREGISTRI.IDCOMUNE      =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE
	AND TIPOLOGIAREGISTRI.TR_ID         =AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO
    LEFT OUTER JOIN CONCESSIONICAUSALI CAUS_STORICO 
	ON CAUS_STORICO.IDCOMUNE           =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE
GO
