Create  View VW_ISTANZEDYN2_DATI as 
SELECT TOP 100 PERCENT istanzedyn2modellit.idcomune,
istanzedyn2modellit.codiceistanza,
istanzedyn2modellit.fk_d2mt_id as idmodello,
dyn2_modellid.posverticale,
dyn2_modellid.posorizzontale,
NULL as tipotesto,
NULL as testo,
istanzedyn2dati.indice,
dyn2_campi.id as idcampo,
dyn2_campi.nomecampo,
istanzedyn2dati.valore FROM dyn2_campi LEFT OUTER JOIN istanzedyn2dati ON dyn2_campi.idcomune=istanzedyn2dati.idcomune  AND dyn2_campi.id=istanzedyn2dati.fk_d2c_id,
dyn2_modellid,
istanzedyn2modellit WHERE dyn2_campi.idcomune = dyn2_modellid.idcomune AND dyn2_campi.id = dyn2_modellid.fk_d2c_id AND dyn2_modellid.idcomune = istanzedyn2modellit.idcomune AND dyn2_modellid.fk_d2mt_id = istanzedyn2modellit.fk_d2mt_id  ORDER BY istanzedyn2modellit.idcomune,
istanzedyn2modellit.codiceistanza,
istanzedyn2modellit.fk_d2mt_id,
dyn2_modellid.posverticale,
dyn2_modellid.posorizzontale
GO
