Create  View VW_ISTANZEDYN2_DATIMODELLO as SELECT istanzedyn2modellit.idcomune,
istanzedyn2modellit.codiceistanza,
istanzedyn2modellit.fk_d2mt_id as idmodello,
dyn2_modellid.posverticale,
dyn2_modellid.posorizzontale,
dyn2_modellidtesti.fk_d2btt_id as tipotesto,
dyn2_modellidtesti.testo,
null as indice,
null as idcampo,
null as nomecampo,
NULL as valore FROM dyn2_modellid LEFT OUTER JOIN dyn2_modellidtesti ON dyn2_modellid.idcomune=dyn2_modellidtesti.idcomune  AND dyn2_modellid.fk_d2mdt_id=dyn2_modellidtesti.id,
istanzedyn2modellit WHERE dyn2_modellid.idcomune = istanzedyn2modellit.idcomune AND dyn2_modellid.fk_d2mt_id = istanzedyn2modellit.fk_d2mt_id UNION  select idcomune,
 codiceistanza,
 idmodello,
 posverticale,
 posorizzontale,
 tipotesto,
 testo,
 indice,
 idcampo,
 nomecampo,
 CAST(SUBSTRING(valore,1,
4000) AS VARCHAR(4000)) from vw_istanzedyn2_dati
GO
