Create  View VW_ISTANZEONERI as SELECT istanze.idcomune,
istanze.software,
istanzeoneri.codiceistanza,
istanzeoneri.id,
istanzeoneri.fkidtipocausale as causale,
tipicausalioneri.co_descrizione as causaleDescrizione,
istanzeoneri.data as dataregistrazione,
istanzeoneri.prezzo as importo,
istanzeoneri.numerorata,
istanzeoneri.datascadenza as datascadenza,
istanzeoneri.datapagamento as dataincasso,
istanzeoneri.fkmodalitapagamento as codicemodalitaincasso,
tipimodalitapagamento.mp_descrestesa as modalitaincasso,
istanzeoneri.docriferimento as riferimentiincasso FROM istanzeoneri LEFT OUTER JOIN tipimodalitapagamento ON istanzeoneri.idcomune=tipimodalitapagamento.idcomune  AND istanzeoneri.fkmodalitapagamento=tipimodalitapagamento.mp_id,
istanze,
tipicausalioneri WHERE istanzeoneri.idcomune = istanze.idcomune AND istanzeoneri.codiceistanza = istanze.codiceistanza AND tipicausalioneri.idcomune = istanzeoneri.idcomune AND tipicausalioneri.co_id = istanzeoneri.fkidtipocausale AND istanzeoneri.flentratauscita = 1 
