Create  View VW_ISTANZEORARI as SELECT ORARIAPERTURATESTATA.ID,
ORARIAPERTURATESTATA.IDCOMUNE,
ORARIAPERTURATESTATA.PERIODODA,
ORARIAPERTURATESTATA.PERIODOA,
ORARIAPERTURATESTATA.CODICEISTANZA,
ORARIAPERTURATESTATA.FKTOID,
ORARIAPERTURA_LUN.OA_DALLEORE as LUN_DALLEORE,
ORARIAPERTURA_LUN.OA_ALLEORE as LUN_ALLEORE,
ORARIAPERTURA_LUN.OA_DALLEOREPOM as LUN_DALLEOREPOM,
ORARIAPERTURA_LUN.OA_ALLEOREPOM as LUN_ALLEOREPOM,
ORARIAPERTURA_LUN.OA_FKIDORARIO as LUN_FKIDORARIO,
TIPIAPERTURA_LUN.TA_DESCRIZIONE as LUN_CHIUSURA,
ORARIAPERTURA_MAR.OA_DALLEORE as MAR_DALLEORE,
ORARIAPERTURA_MAR.OA_ALLEORE as MAR_ALLEORE,
ORARIAPERTURA_MAR.OA_DALLEOREPOM as MAR_DALLEOREPOM,
ORARIAPERTURA_MAR.OA_ALLEOREPOM as MAR_ALLEOREPOM,
ORARIAPERTURA_MAR.OA_FKIDORARIO as MAR_FKIDORARIO,
TIPIAPERTURA_MAR.TA_DESCRIZIONE as MAR_CHIUSURA,
ORARIAPERTURA_MER.OA_DALLEORE as MER_DALLEORE,
ORARIAPERTURA_MER.OA_ALLEORE as MER_ALLEORE,
ORARIAPERTURA_MER.OA_DALLEOREPOM as MER_DALLEOREPOM,
ORARIAPERTURA_MER.OA_ALLEOREPOM as MER_ALLEOREPOM,
ORARIAPERTURA_MER.OA_FKIDORARIO as MER_FKIDORARIO,
TIPIAPERTURA_MER.TA_DESCRIZIONE as MER_CHIUSURA,
ORARIAPERTURA_GIO.OA_DALLEORE as GIO_DALLEORE,
ORARIAPERTURA_GIO.OA_ALLEORE as GIO_ALLEORE,
ORARIAPERTURA_GIO.OA_DALLEOREPOM as GIO_DALLEOREPOM,
ORARIAPERTURA_GIO.OA_ALLEOREPOM as GIO_ALLEOREPOM,
ORARIAPERTURA_GIO.OA_FKIDORARIO as GIO_FKIDORARIO,
TIPIAPERTURA_GIO.TA_DESCRIZIONE as GIO_CHIUSURA,
ORARIAPERTURA_VEN.OA_DALLEORE as VEN_DALLEORE,
ORARIAPERTURA_VEN.OA_ALLEORE as VEN_ALLEORE,
ORARIAPERTURA_VEN.OA_DALLEOREPOM as VEN_DALLEOREPOM,
ORARIAPERTURA_VEN.OA_ALLEOREPOM as VEN_ALLEOREPOM,
ORARIAPERTURA_VEN.OA_FKIDORARIO as VEN_FKIDORARIO,
TIPIAPERTURA_VEN.TA_DESCRIZIONE as VEN_CHIUSURA,
ORARIAPERTURA_SAB.OA_DALLEORE as SAB_DALLEORE,
ORARIAPERTURA_SAB.OA_ALLEORE as SAB_ALLEORE,
ORARIAPERTURA_SAB.OA_DALLEOREPOM as SAB_DALLEOREPOM,
ORARIAPERTURA_SAB.OA_ALLEOREPOM as SAB_ALLEOREPOM,
ORARIAPERTURA_SAB.OA_FKIDORARIO as SAB_FKIDORARIO,
TIPIAPERTURA_SAB.TA_DESCRIZIONE as SAB_CHIUSURA,
ORARIAPERTURA_DOM.OA_DALLEORE as DOM_DALLEORE,
ORARIAPERTURA_DOM.OA_ALLEORE as DOM_ALLEORE,
ORARIAPERTURA_DOM.OA_DALLEOREPOM as DOM_DALLEOREPOM,
ORARIAPERTURA_DOM.OA_ALLEOREPOM as DOM_ALLEOREPOM,
ORARIAPERTURA_DOM.OA_FKIDORARIO as DOM_FKIDORARIO,
TIPIAPERTURA_DOM.TA_DESCRIZIONE as DOM_CHIUSURA FROM ORARIAPERTURATESTATA LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_LUN LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_LUN ON ORARIAPERTURA_LUN.IDCOMUNE=TIPIAPERTURA_LUN.IDCOMUNE  AND ORARIAPERTURA_LUN.OA_FKIDORARIO=TIPIAPERTURA_LUN.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_LUN.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_LUN.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_MAR LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_MAR ON ORARIAPERTURA_MAR.IDCOMUNE=TIPIAPERTURA_MAR.IDCOMUNE  AND ORARIAPERTURA_MAR.OA_FKIDORARIO=TIPIAPERTURA_MAR.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_MAR.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_MAR.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_MER LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_MER ON ORARIAPERTURA_MER.IDCOMUNE=TIPIAPERTURA_MER.IDCOMUNE  AND ORARIAPERTURA_MER.OA_FKIDORARIO=TIPIAPERTURA_MER.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_MER.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_MER.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_GIO LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_GIO ON ORARIAPERTURA_GIO.IDCOMUNE=TIPIAPERTURA_GIO.IDCOMUNE  AND ORARIAPERTURA_GIO.OA_FKIDORARIO=TIPIAPERTURA_GIO.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_GIO.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_GIO.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_VEN LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_VEN ON ORARIAPERTURA_VEN.IDCOMUNE=TIPIAPERTURA_VEN.IDCOMUNE  AND ORARIAPERTURA_VEN.OA_FKIDORARIO=TIPIAPERTURA_VEN.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_VEN.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_VEN.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_SAB LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_SAB ON ORARIAPERTURA_SAB.IDCOMUNE=TIPIAPERTURA_SAB.IDCOMUNE  AND ORARIAPERTURA_SAB.OA_FKIDORARIO=TIPIAPERTURA_SAB.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_SAB.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_SAB.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_DOM LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_DOM ON ORARIAPERTURA_DOM.IDCOMUNE=TIPIAPERTURA_DOM.IDCOMUNE  AND ORARIAPERTURA_DOM.OA_FKIDORARIO=TIPIAPERTURA_DOM.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_DOM.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_DOM.OA_FKIDTESTATA WHERE ( ORARIAPERTURA_LUN.OA_FKIDGIORNO = 1 or ORARIAPERTURA_LUN.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_MAR.OA_FKIDGIORNO = 2 or ORARIAPERTURA_MAR.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_MER.OA_FKIDGIORNO = 3 or ORARIAPERTURA_MER.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_GIO.OA_FKIDGIORNO = 4 or ORARIAPERTURA_GIO.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_VEN.OA_FKIDGIORNO = 5 or ORARIAPERTURA_MAR.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_SAB.OA_FKIDGIORNO = 6 or ORARIAPERTURA_SAB.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_DOM.OA_FKIDGIORNO = 7 or ORARIAPERTURA_DOM.OA_FKIDGIORNO  is  NULL ) 
GO
