Create  View VW_ISTANZEPROCEDIMENTI as SELECT ISTANZEPROCEDIMENTI.CODICEISTANZA,
ISTANZEPROCEDIMENTI.CODICEINVENTARIO,
INVENTARIOPROCEDIMENTI.PROCEDIMENTO,
ISTANZEPROCEDIMENTI.PERPROVVEDIMENTO,
ISTANZEPROCEDIMENTI.ACQUISITO,
ISTANZEPROCEDIMENTI.COSTORICHIESTO,
ISTANZEPROCEDIMENTI.COSTOPAGATO,
ISTANZEPROCEDIMENTI.PROC_NUM,
ISTANZEPROCEDIMENTI.PROT_NUM,
ISTANZEPROCEDIMENTI.PROC_DEL,
ISTANZEPROCEDIMENTI.PROT_DEL,
ISTANZEPROCEDIMENTI.DATAATTIVAZIONE,
ISTANZEPROCEDIMENTI.IDCOMUNE,
ISTANZEPROCEDIMENTI.ELIMINATO,
ISTANZEPROCEDIMENTI.FLAG_COMMISSIONE FROM  ISTANZEPROCEDIMENTI,
 INVENTARIOPROCEDIMENTI WHERE INVENTARIOPROCEDIMENTI.IDCOMUNE = ISTANZEPROCEDIMENTI.IDCOMUNE and INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = ISTANZEPROCEDIMENTI.CODICEINVENTARIO
