Drop View VW_ISTANZESOGGETTICOLLEGATI
GO
Create  View VW_ISTANZESOGGETTICOLLEGATI as 
SELECT 'S' as TIPOLOGIA,
ISTANZERICHIEDENTI.CODICEISTANZA,
ISTANZERICHIEDENTI.CODICERICHIEDENTE,
ISTANZERICHIEDENTI.CODICEINVITATO,
ISTANZERICHIEDENTI.CODICETIPOSOGGETTO,
ISTANZERICHIEDENTI.IDCOMUNE,
ISTANZERICHIEDENTI.CODICEANAGRAFECOLL,
ISNULL(ISTANZERICHIEDENTI.DESCRSOGGETTO,
 TIPISOGGETTO.TIPOSOGGETTO ) as DESCRSOGGETTO,
ISTANZERICHIEDENTI.CODICEPROCURATORE,
ISTANZE.FK_IDI_ATTIVITA FROM  ISTANZERICHIEDENTI,
 ISTANZE,
 TIPISOGGETTO WHERE TIPISOGGETTO.IDCOMUNE = ISTANZERICHIEDENTI.IDCOMUNE and TIPISOGGETTO.CODICETIPOSOGGETTO = ISTANZERICHIEDENTI.CODICETIPOSOGGETTO and ISTANZERICHIEDENTI.IDCOMUNE = ISTANZE.IDCOMUNE and ISTANZERICHIEDENTI.CODICEISTANZA = ISTANZE.CODICEISTANZA UNION SELECT 'R' as TIPOLOGIA,
ISTANZE.CODICEISTANZA,
ISTANZE.CODICERICHIEDENTE,
NULL as CODICEINVITATO,
NULL as CODICETIPOSOGGETTO,
ISTANZE.IDCOMUNE,
NULL as CODICEANAGRAFECOLL,
ISNULL(TIPISOGGETTO.TIPOSOGGETTO,
 'RICHIEDENTE' ) as DESCRSOGGETTO,
NULL as CODICEPROCURATORE,
FK_IDI_ATTIVITA FROM ISTANZE LEFT OUTER JOIN TIPISOGGETTO ON ISTANZE.IDCOMUNE=TIPISOGGETTO.IDCOMUNE  AND ISTANZE.FKCODICESOGGETTO=TIPISOGGETTO.CODICETIPOSOGGETTO UNION SELECT 'A' as TIPOLOGIA,
ISTANZE.CODICEISTANZA,
ISTANZE.CODICETITOLARELEGALE,
NULL as CODICEINVITATO,
NULL as CODICETIPOSOGGETTO,
ISTANZE.IDCOMUNE,
NULL as CODICEANAGRAFECOLL,
'RAGIONE SOCIALE' as DESCRSOGGETTO,
NULL as CODICEPROCURATORE,
FK_IDI_ATTIVITA FROM  ISTANZE WHERE NOT CODICETITOLARELEGALE  is  NULL UNION SELECT 'T' as TIPOLOGIA,
ISTANZE.CODICEISTANZA,
ISTANZE.CODICEPROFESSIONISTA,
NULL as CODICEINVITATO,
NULL as CODICETIPOSOGGETTO,
ISTANZE.IDCOMUNE,
NULL as CODICEANAGRAFECOLL,
'PROFESSIONISTA' as DESCRSOGGETTO,
NULL as CODICEPROCURATORE,
FK_IDI_ATTIVITA FROM  ISTANZE WHERE NOT CODICEPROFESSIONISTA  is  NULL
GO
Drop View VW_LISTAPRATICHE
GO
Create  View VW_LISTAPRATICHE as SELECT istanze.codicecomune,
istanze.idcomune,
istanze.software as software,
software.descrizionelunga as descsoftware,
istanze.codiceistanza as idpratica,
istanze.numeroistanza as numeropratica,
CONVERT(VARCHAR,
istanze.data,
103) as datapresentazione,
YEAR(istanze.data) as annopresentazione,
MONTH(istanze.data) as mesepresentazione,
istanze.numeroprotocollo,
CONVERT(VARCHAR,
istanze.dataprotocollo,
103) as dataprotocollo,
istanze.codiceinterventoproc as codiceintervento,
vw_alberoproc.sc_descrizione as descrizioneintervento,
tipiprocedure.codiceprocedura,
tipiprocedure.procedura,
istanze.lavori as oggetto,
UPPER(istanze.lavori) as oggettou,
istanze.chiusura as codstatopratica,
stato as statopratica,
responsabili.responsabile,
responsabili.telefonolavoro as responsabile_telefono,
ISNULL(stradario.codviario,
stradario.codicestradario) as pr_codviario,
ISNULL(stradario.prefisso,
'') + ISNULL(' ',
'') + ISNULL(stradario.descrizione,
'') as pr_indirizzo,
istanzestradario.CODICECIVICO as pr_codcivico,
istanze.civico as pr_civico,
istanze.codicearea as codicezonizzazione,
aree.denominazione as zonizzazione,
anagrafe.codiceanagrafe as CodiceRichiedente,
ISNULL(anagrafe.codicefiscale,
 '') as codicefiscale,
ISNULL(anagrafe.partitaiva,
 '') as partitaiva,
ISNULL(anagrafe.nominativo,
'') + ISNULL(' ',
'') + ISNULL(anagrafe.nome,
'') as nominativo,
anagrafe.indirizzo,
anagrafe.cap,
anagrafe.citta as localita,
comuneresidenza.comune as citta,
comuneresidenza.provincia,
tipisoggetto.tiposoggetto as tiporapporto,
catasto.descrizione as tipocatasto,
istanzemappali.foglio,
istanzemappali.particella,
istanzemappali.sub,
tecnico.codiceanagrafe as tec_codice,
ISNULL(tecnico.nominativo,
'') + ISNULL(' ',
'') + ISNULL(tecnico.nome,
'') as tec_nominativo,
ISNULL(tecnico.codicefiscale,
 '') as tec_codicefiscale,
ISNULL(tecnico.partitaiva,
 '') as tec_partitaiva,
azienda.codiceanagrafe as az_codice,
ISNULL(azienda.nominativo,
'') + ISNULL(' ',
'') + ISNULL(azienda.nome,
'') as az_nominativo,
ISNULL(azienda.codicefiscale,
 '') as az_codicefiscale,
ISNULL(azienda.partitaiva,
 '') as az_partitaiva,
istruttori.responsabile as istruttore,
istruttori.telefonolavoro as istruttore_telefono,
operatori.responsabile as operatore,
operatori.telefonolavoro as operatore_telefono FROM istanze LEFT OUTER JOIN anagrafe tecnico ON istanze.idcomune=tecnico.idcomune  AND istanze.codiceprofessionista=tecnico.codiceanagrafe  LEFT OUTER JOIN anagrafe azienda ON istanze.idcomune=azienda.idcomune  AND istanze.codicetitolarelegale=azienda.codiceanagrafe  LEFT OUTER JOIN istanzemappali LEFT OUTER JOIN catasto ON istanzemappali.codicecatasto=catasto.codice ON istanze.idcomune=istanzemappali.idcomune  AND istanze.codiceistanza=istanzemappali.fkcodiceistanza  LEFT OUTER JOIN responsabili ON istanze.idcomune=responsabili.idcomune  AND istanze.codiceresponsabileproc=responsabili.codiceresponsabile  LEFT OUTER JOIN tipisoggetto ON istanze.idcomune=tipisoggetto.idcomune  AND istanze.fkcodicesoggetto=tipisoggetto.codicetiposoggetto  LEFT OUTER JOIN aree ON istanze.idcomune=aree.idcomune  AND istanze.codicearea=aree.codicearea  LEFT OUTER JOIN tipiprocedure ON istanze.idcomune=tipiprocedure.idcomune  AND istanze.codiceprocedura=tipiprocedure.codiceprocedura  LEFT OUTER JOIN responsabili istruttori ON istanze.idcomune=istruttori.idcomune  AND istanze.codiceistruttore=istruttori.codiceresponsabile  LEFT OUTER JOIN responsabili operatori ON istanze.idcomune=operatori.idcomune  AND istanze.codiceresponsabile=operatori.codiceresponsabile,
anagrafe LEFT OUTER JOIN comuni comuneresidenza ON anagrafe.comuneresidenza=comuneresidenza.codicecomune,
software,
istanzestradario,
stradario,
vw_alberoproc,
statiistanza WHERE software.codice = istanze.software AND anagrafe.idcomune = istanze.idcomune AND anagrafe.codiceanagrafe = istanze.codicerichiedente AND statiistanza.idcomune = istanze.idcomune AND statiistanza.software = istanze.software AND statiistanza.codicestato = istanze.chiusura AND istanzestradario.idcomune = istanze.idcomune AND istanzestradario.codiceistanza = istanze.codiceistanza AND istanzestradario.primario = 1 AND stradario.idcomune = istanzestradario.idcomune AND stradario.codicestradario = istanzestradario.codicestradario AND istanzemappali.primario = 1 AND vw_alberoproc.idcomune = istanze.idcomune AND vw_alberoproc.sc_id = istanze.codiceinterventoproc 
GO
Drop View VW_ONERIREGULUS
GO
Create  View VW_ONERIREGULUS as SELECT istanzeoneri.idcomune,
istanzeoneri.fkidtipocausale,
count(istanzeoneri.numerorata) as numerorate,
istanzeoneri.codiceistanza,
sum(istanzeoneri.prezzo) as importo,
istanze.codicerichiedente as richiedente,
anagrafe.codicefiscale as codifiscale,
anagrafe.partitaiva as partitaiva,
impresa.codicefiscale as codifiscale_impresa,
impresa.partitaiva as partitaiva_impresa,
tipicausalioneri.pagamentiregulus,
tipicausalioneri.fkidcausalebollo,
istanzeoneri.nr_documento FROM istanze LEFT OUTER JOIN anagrafe impresa ON istanze.idcomune = impresa.idcomune AND istanze.codicetitolarelegale = impresa.codiceanagrafe,
istanzeoneri,
anagrafe,
tipicausalioneri WHERE istanzeoneri.idcomune = istanze.idcomune AND istanzeoneri.codiceistanza = istanze.codiceistanza AND istanze.idcomune = anagrafe.idcomune AND istanze.codicerichiedente = anagrafe.codiceanagrafe AND tipicausalioneri.idcomune = istanzeoneri.idcomune AND tipicausalioneri.co_id = istanzeoneri.fkidtipocausale AND tipicausalioneri.pagamentiregulus = 1  GROUP BY istanzeoneri.fkidtipocausale,
istanzeoneri.codiceistanza,
istanzeoneri.idcomune,
istanze.codicerichiedente,
anagrafe.codicefiscale,
anagrafe.partitaiva,
impresa.codicefiscale,
impresa.partitaiva,
tipicausalioneri.pagamentiregulus,
tipicausalioneri.fkidcausalebollo,
istanzeoneri.nr_documento
GO
Drop View VW_POSTEGGICONCESSIONI
GO
Create  View VW_POSTEGGICONCESSIONI as SELECT vw_posteggimercatouso.IDCOMUNE,
vw_posteggimercatouso.CODICEMERCATO,
vw_posteggimercatouso.IDUSO,
vw_posteggimercatouso.IDPOSTEGGIO,
vw_concessioniattive.codiceconcessione,
vw_concessioniattive.codiceistanza,
vw_concessioniattive.codiceoccupante,
vw_concessioniattive.codicetitolare FROM vw_posteggimercatouso LEFT OUTER JOIN vw_concessioniattive ON vw_posteggimercatouso.idcomune=vw_concessioniattive.idcomune  AND vw_posteggimercatouso.codicemercato=vw_concessioniattive.fk_codicemercato  AND vw_posteggimercatouso.iduso=vw_concessioniattive.fk_idmercatiuso  AND vw_posteggimercatouso.idposteggio=vw_concessioniattive.fk_idposteggio
