Create  View VW_REGISTRAZIONIDEBITI as SELECT id_REGISTRAZIONE,
IDCOMUNE,
SOFTWARE,
count(rata_non_pagata) as rate_non_pagate,
SUM(importo_rata) as importo_rate,
SUM(incassato_rata) as incassato_rate,
(SUM(importo_rata) - ISNULL(SUM(incassato_rata),
0)) as DA_INCASSARE FROM  	VW_A_REGISTRAZIONI_DEBITI GROUP BY id_registrazione,
SOFTWARE,
IDCOMUNE
