Drop View VW_REGISTRAZIONISALDO
GO
Create  View VW_REGISTRAZIONISALDO as 
SELECT importi_non_ridotti.id as id,
importi_non_ridotti.idcomune as idcomune,
importi_non_ridotti.importo_registrazione as importo_registrazione,
importi_non_ridotti.incassato + importi_ridotti.incassato as incassato,
importi_ridotti.incassato as incassato_ridotto,
(saldo_ridotti.saldo - importi_ridotti.incassato) as saldo_ridotto,
importi_non_ridotti.incassato as incassato_non_ridotto,
importi_non_ridotti.saldo as saldo_non_ridotto,
case SIGN(importi_non_ridotti.importo_registrazione) 
when 1 
then  
	case importi_ridotti.incassato 
	when 0 
	then  
		((importi_non_ridotti.saldo - ISNULL(saldo_ridotti.saldo,0)) - (importi_non_ridotti.incassato-(importi_non_ridotti.incassato + importi_ridotti.incassato)))  
	ELSE  
		( importi_non_ridotti.importo_registrazione -(importi_non_ridotti.incassato + ISNULL(saldo_ridotti.saldo,0)))  
	end  
ELSE 0 
end as saldo 
FROM vw_a_importi_ridotti importi_non_ridotti 
LEFT OUTER JOIN vw_a_importi_ridotti importi_ridotti 
ON importi_non_ridotti.idcomune=importi_ridotti.idcomune  
AND importi_non_ridotti.id=importi_ridotti.id  
LEFT OUTER JOIN vw_a_saldo_ridotti saldo_ridotti 
ON importi_non_ridotti.idcomune=saldo_ridotti.idcomune  
AND importi_non_ridotti.id=saldo_ridotti.id
GO
