Create  View VW_SCADENZARIO as SELECT BATCH_SCADENZARIO.IDCOMUNE as IDCOMUNE,
BATCH_SCADENZARIO.ID as CODICESCADENZA,
BATCH_SCADENZARIO.SOFTWARE as software,
BATCH_SCADENZARIO.CODICEISTANZA as codiceistanza,
ISTANZE.NUMEROPROTOCOLLO as numeroprotocollo,
ISTANZE.DATAPROTOCOLLO as dataprotocollo,
ISTANZE.NUMEROISTANZA as NUMEROISTANZA,
ISTANZE.CHIUSURA as CODSTATOISTANZA,
STATIISTANZA.STATO as DESCRSTATOISTANZA,
BATCH_SCADENZARIO.CODICEMOVIMENTO as CODMOVIMENTO,
BATCH_SCADENZARIO.DESCRMOVIMENTO as DESCRMOVIMENTO,
CONVERT(VARCHAR,
MOVIMENTI.DATA,
103) as DATAMOVIMENTO,
BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE as CODMOVIMENTODAFARE,
BATCH_SCADENZARIO.DESCRMOVIMENTODAFARE as DESCRMOVIMENTODAFARE,
CONVERT(VARCHAR,
BATCH_SCADENZARIO.DATASCADENZA,
103) as DATASCADENZASTR,
BATCH_SCADENZARIO.codiceinventario as codiceinventario,
BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE as CODICEAMMINISTRAZIONE,
RESPONSABILI.RESPONSABILE as RESPONSABILE,
INVENTARIOPROCEDIMENTI.PROCEDIMENTO as PROCEDIMENTO,
TIPIPROCEDURE.PROCEDURA as PROCEDURA,
SOFTWARE.DESCRIZIONE as MODULOSOFTWARE,
amministrazioni.AMMINISTRAZIONE as AMM_amministrazione,
AMMINISTRAZIONI.PARTITAIVA as AMM_PARTITAIVA,
AMMINISTRAZIONI.PASSWORD as AMM_PASSWORD,
ISNULL(ANAGRAFE.NOMINATIVO,
'') + ISNULL(' ',
'') + ISNULL(ANAGRAFE.NOME,
'') as RIC_NOMINATIVO,
ISNULL(ANAGRAFE.CODICEFISCALE,
'') as RIC_CODICEFISCALE,
ISNULL(ANAGRAFE.PARTITAIVA,
'') as RIC_PARTITAIVA,
ANAGRAFE.INDIRIZZO as RIC_INDIRIZZO,
ANAGRAFE.CAP as RIC_CAP,
ANAGRAFE.CITTA as RIC_LOCALITA,
COMUNERESIDENZA.COMUNE as RIC_CITTA,
COMUNERESIDENZA.PROVINCIA as RIC_PROVINCIA,
ANAGRAFE.PASSWORD as RIC_PASSWORD,
ISNULL(TECNICO.NOMINATIVO,
'') + ISNULL(' ',
'') + ISNULL(TECNICO.NOME,
'') as TEC_NOMINATIVO,
ISNULL(TECNICO.CODICEFISCALE,
'') as TEC_CODICEFISCALE,
ISNULL(TECNICO.PARTITAIVA,
'') as TEC_PARTITAIVA,
TECNICO.PASSWORD as TEC_PASSWORD,
ISNULL(AZIENDA.NOMINATIVO,
'') + ISNULL(' ',
'') + ISNULL(AZIENDA.NOME,
'') as AZ_NOMINATIVO,
ISNULL(AZIENDA.CODICEFISCALE,
'') as AZ_CODICEFISCALE,
ISNULL(AZIENDA.PARTITAIVA,
'') as AZ_PARTITAIVA,
AZIENDA.PASSWORD as AZ_PASSWORD,
TIPIMOVIMENTO.FK_FO_SOGGETTIESTERNI FROM ANAGRAFE LEFT OUTER JOIN COMUNI COMUNERESIDENZA ON ANAGRAFE.COMUNERESIDENZA=COMUNERESIDENZA.CODICECOMUNE,
ISTANZE LEFT OUTER JOIN ANAGRAFE TECNICO ON ISTANZE.IDCOMUNE=TECNICO.IDCOMUNE  AND ISTANZE.CODICEPROFESSIONISTA=TECNICO.CODICEANAGRAFE  LEFT OUTER JOIN ANAGRAFE AZIENDA ON ISTANZE.IDCOMUNE=AZIENDA.IDCOMUNE  AND ISTANZE.CODICETITOLARELEGALE=AZIENDA.CODICEANAGRAFE,
BATCH_SCADENZARIO,
RESPONSABILI,
INVENTARIOPROCEDIMENTI,
MOVIMENTI,
TIPIPROCEDURE,
SOFTWARE,
STATIISTANZA,
AMMINISTRAZIONI,
TIPIMOVIMENTO WHERE ISTANZE.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND ISTANZE.CODICEISTANZA = BATCH_SCADENZARIO.CODICEISTANZA AND RESPONSABILI.IDCOMUNE = ISTANZE.IDCOMUNE AND RESPONSABILI.CODICERESPONSABILE = ISTANZE.CODICERESPONSABILE AND INVENTARIOPROCEDIMENTI.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = BATCH_SCADENZARIO.CODICEINVENTARIO AND MOVIMENTI.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND MOVIMENTI.CODICEMOVIMENTO = BATCH_SCADENZARIO.CODICEMOVIMENTO AND TIPIMOVIMENTO.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND TIPIMOVIMENTO.TIPOMOVIMENTO = BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE AND TIPIPROCEDURE.IDCOMUNE = ISTANZE.IDCOMUNE AND TIPIPROCEDURE.CODICEPROCEDURA = ISTANZE.CODICEPROCEDURA AND SOFTWARE.CODICE = BATCH_SCADENZARIO.SOFTWARE AND ANAGRAFE.IDCOMUNE = ISTANZE.IDCOMUNE AND ANAGRAFE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA AND AMMINISTRAZIONI.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE AND AMMINISTRAZIONI.CODICEAMMINISTRAZIONE = BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE 
GO
