ISTANZE.CODICERICHIEDENTE,
ISTANZE.CODICEPROFESSIONISTA,
ISTANZE.DATA,
ISTANZE.NUMEROPROTOCOLLO,
ISTANZE.DATAPROTOCOLLO,
ISTANZE.CODICEINTERVENTO,
ISTANZE.LAVORI,
ISTANZE.CODICEPROCEDURA,
ISTANZE.CODICEAREA,
ISTANZE.CODICELOTTO,
ISTANZE.PASSWORD,
ISTANZE.ATTIVA,
ISTANZE.FOGLIO,
ISTANZE.PARTICELLA,
ISTANZE.SUB,
ISTANZE.CODICESETTORE,
ISTANZE.VARIANTEPR,
ISTANZE.CODICEIMPIANTO,
ISTANZE.CODICEATTIVITA,
ISTANZE.FLAGVIA,
ISTANZE.CHIUSURA,
ISTANZE.PROGREGAUT,
ISTANZE.LAVORIESTESA,
ISTANZE.CODICEARCHIVIO,
ISTANZE.CODICESTRADARIO,
ISTANZE.CIVICO,
ISTANZE.AUTORIZNUMERO,
ISTANZE.AUTORIZDATA,
ISTANZE.AUTORIZDATAREGISTR,
ISTANZE.AUTORIZRESPONSABILE,
ISTANZE.TIPOMOVAVVIO,
ISTANZE.TIPOARCHIVIO,
ISTANZE.CODICECOMUNE,
ISTANZE.SOFTWARE,
ISTANZE.IDMODELLO,
ISTANZE.CODICEINTERVENTOPROC,
ISTANZE.NUMEROISTANZA,
ISTANZE.IDCOMUNE,
ISTANZE.SETITOLARELEGALE,
ISTANZE.FKIDTIPOLOGIAISTANZA,
ISTANZE.CODICETITOLARELEGALE,
ISTANZE.FKTOID,
ISTANZE.METRIQUADRATI,
ISTANZE.GIORNOCHIUSURA,
ISTANZE.CODISTANZACOLLEGATA,
ISTANZE.AZIONE,
ISTANZE.FKIDREGISTRO,
ISTANZE.NOMEATTIVITA,
ISTANZE.FKIDFORMATO,
ISTANZE.POSIZIONEARCHIVIO,
ISTANZE.BASE,
ISTANZE.ALTEZZA,
ISTANZE.FACCE,
ISTANZE.FKIDPROTOCOLLO,
ISTANZE.FKCODICESOGGETTO,
ISTANZE.CODICEISTRUTTORE,
ISTANZE.CODICERESPONSABILEPROC,
ISTANZE.CODICEAREA2,
